begin;
create extension if not exists pgtap with schema extensions;
select extensions.no_plan();
select extensions.ok((select rowsecurity from pg_tables where schemaname='public' and tablename='knowledge_collections'),'Collections have RLS');
select extensions.ok(not has_table_privilege('anon','public.knowledge_collections','SELECT'),'Anonymous collection reads denied');
select extensions.ok(not has_table_privilege('authenticated','public.knowledge_collections','INSERT'),'Collection writes require owner RPC');
select extensions.ok(not has_table_privilege('authenticated','public.knowledge_collections','UPDATE'),'Raw collection rename denied');
select extensions.ok(not has_table_privilege('authenticated','public.knowledge_collections','DELETE'),'Raw collection delete denied');
select extensions.ok(not has_function_privilege('anon','public.save_business_knowledge(uuid,uuid,text,text,text,integer,text,text,text,uuid)','EXECUTE'),'Anonymous structured writes denied');
insert into auth.users(id,aud,role,email) values
 ('ad111111-1111-4111-8111-111111111111','authenticated','authenticated','knowledge-owner@example.test'),
 ('ad222222-2222-4222-8222-222222222222','authenticated','authenticated','knowledge-outsider@example.test'),
 ('ad333333-3333-4333-8333-333333333333','authenticated','authenticated','knowledge-member@example.test');
do $$ begin perform set_config('test.kvector','['||'1,'||repeat('0,',1534)||'0]',true); end $$;
set local role authenticated;
set local request.jwt.claims='{"sub":"ad111111-1111-4111-8111-111111111111","role":"authenticated"}';
do $$ begin
 perform set_config('test.kworkspace',public.create_workspace('Knowledge Studio')::text,true);
 perform set_config('test.kcollection',public.save_knowledge_collection(current_setting('test.kworkspace')::uuid,null,'Services')::text,true);
 perform set_config('test.kconnection',public.configure_website_channel(current_setting('test.kworkspace')::uuid,true,array['https://knowledge.example'])::text,true);
 perform set_config('test.kpublic',(select public_id::text from public.channel_connections where id=current_setting('test.kconnection')::uuid),true);
end $$;
select extensions.lives_ok($$select public.save_knowledge_collection(current_setting('test.kworkspace')::uuid,current_setting('test.kcollection')::uuid,'Studio services')$$,'Owner can rename a collection');
select extensions.throws_ok($$select public.save_knowledge_collection(current_setting('test.kworkspace')::uuid,null,'studio services')$$,'23505',null,'Duplicate names rejected case-insensitively');
set local role service_role;
set local request.jwt.claims='{"role":"service_role"}';
select public.create_website_session(current_setting('test.kpublic')::uuid,'https://knowledge.example',repeat('a',64));
do $$ declare r record; begin
 select * into r from public.begin_website_turn(current_setting('test.kpublic')::uuid,'https://knowledge.example',repeat('a',64),gen_random_uuid(),'What are your business services and prices?');
 perform set_config('test.krun',r.run_id::text,true);
end $$;
set local role authenticated;
set local request.jwt.claims='{"sub":"ad111111-1111-4111-8111-111111111111","role":"authenticated"}';


